fn fibonacci(n: usize) -> Vec<i32> {
    let mut fib = Vec::with_capacity(n);
    fib.push(0);
    fib.push(1);
    for i in 2..n {
        // Safe to unwrap here since previous two elements must exist
        let next = fib[i - 1] + fib[i - 2];
        fib.push(next);
    }
    fib
}